body:
Added functions to convert between year and day from unix timestamps in constant time, to avoid having to iterate one year at a time.

Closes #106695.

Tested with gdscript below:

```gdscript
func _ready() -> void:
	run_test("distant_time")
	run_test("near_times")
	run_test("validate_times")
	
func run_test(p_name : String):
	var start := Time.get_ticks_msec()
	call(p_name)
	var end := Time.get_ticks_msec()
	print("%s: %dms" % [p_name, end - start])

func distant_time():
	print(Time.get_datetime_dict_from_unix_time(-50000000000000000))
	print(Time.get_datetime_dict_from_unix_time(50000000000000000))

func near_times():
	for i in 100000:
		Time.get_datetime_dict_from_unix_time(10000 * i)
		Time.get_datetime_dict_from_unix_time(-10000 * i)

func validate_times():
	var file := FileAccess.open("res://time.txt", FileAccess.READ)
	while !file.eof_reached():
		var line := file.get_line()
		if line.is_empty():
			continue
		var datestr = line.substr(0, line.find(","))
		var seconds = line.substr(line.find(",") + 1).to_int()
		var converted_seconds = Time.get_unix_time_from_datetime_string(datestr)
		var converted_string = Time.get_datetime_string_from_unix_time(seconds, true)
		if (converted_seconds != seconds):
			print("Error converting to seconds: %s -- result: %d" % [line, converted_seconds])
		if (converted_string != datestr):
			print("Error converting to string: %s -- result: %s" % [line, converted_string])
```

old:
```
{ "year": -1584434956, "month": 8, "day": 29, "weekday": 4, "hour": 7, "minute": 6, "second": 40 }
{ "year": 1584438895, "month": 5, "day": 4, "weekday": 3, "hour": 16, "minute": 53, "second": 20 }
distant_time: 2910ms
near_times: 278ms
validate_times: 372771ms
```

new:
```
{ "year": -1584434956, "month": 8, "day": 29, "weekday": 4, "hour": 7, "minute": 6, "second": 40 }
{ "year": 1584438895, "month": 5, "day": 4, "weekday": 3, "hour": 16, "minute": 53, "second": 20 }
distant_time: 0ms
near_times: 277ms
validate_times: 114472ms

```

The `res://time.txt` file used in `validate_times` was generated with c++ code below, writing one line for every 6 hours from Jan 1, -10000 to Jan 1, 10000, with both the formatted date string and seconds integer separated by a comma:

```c++
#include <cstdint>
#include <cstdio>
#include <ctime>

int main()
{
	using namespace std;
	const int64_t INTERVAL = 86400 / 4;
	const int64_t START = -377736739200;
	const int64_t END = 253402300800;
	
	for (time_t seconds = START; seconds <= END; seconds += INTERVAL) {
		tm *dt = gmtime(&seconds);
		printf("%04d-%02d-%02d %02d:%02d:%02d,%ld",
			dt->tm_year + 1900, dt->tm_mon + 1, dt->tm_mday,
			dt->tm_hour, dt->tm_min, dt->tm_sec,
			seconds);
		printf("\n");
	}
	return 0;
}
```

